const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
sd.pvSyncResults=[];
sd.threadStats={checked:0,updated:0,problems:[]};
sd.clientMap={};
// Scheduled runs sync every PV client. A launched run with a Client on its launch row syncs that client only.
const cf=String((sd.launch||{}).clientFilter||'');
const all=$input.all().filter(it=>it.json&&it.json.id);
const picked=cf?all.filter(it=>it.json.id===cf):all;
sd.syncScope=cf?(picked.length?'one client (on demand)':'client filter matched no PV client'):'all clients';
for(const it of picked){ const r=it.json||{}; const f=r.fields||r; sd.clientMap[r.id]={name:f['Client']||'', pvWorkspace:String(f['PlusVibe Workspace ID']||'').trim()}; }
// Nothing to loop over: emit one placeholder so the Any Clients? gate can route straight to the run log.
if(!picked.length) return [{ json: { _empty:true } }];
return picked;

// Keeps only prospects whose client is in this run's scope (the PV clients picked by Init Results).
// A prospect of a client outside the scope (an Alta client, a non-PV client, a client filtered out
// on an on-demand run) is out of scope, not a thread problem: counted once as a skip, never as an error.
const sd=$getWorkflowStaticData('global');
const cm=sd.clientMap||{};
const toId=(c)=>typeof c==='string'?c:((c&&c.id)||'');
let scopeSkipped=0;
const items=[];
for(const it of $input.all()){
  if(!it||!it.json||!it.json.id) continue;
  const f=it.json.fields||it.json;
  const cl=Array.isArray(f.Client)?f.Client.map(toId):[];
  if(!cl.length||!cm[cl[0]]){ scopeSkipped++; continue; }
  items.push(it);
}
sd.threadStats=sd.threadStats||{checked:0,updated:0,problems:[]};
sd.threadStats.scopeSkipped=scopeSkipped;
if(!items.length) return [{ json: { _empty:true } }];
return items;

let results=[]; let t={checked:0,updated:0,problems:[]}; let rs=0; let launch={}; let scope='all clients';
try{ const sd=$getWorkflowStaticData('global'); results=sd.pvSyncResults||[]; t=sd.threadStats||t; rs=sd.runStartedAt||0; launch=sd.launch||{}; scope=sd.syncScope||scope; }catch(e){}
const failed=results.filter(r=>!r.ok);
const totalIn=results.reduce((s,r)=>s+(r.campaigns||0),0);
const totalOut=results.reduce((s,r)=>s+(r.written||0),0);
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const lines=results.map(r=> '- **'+r.client+':** '+nf(r.campaigns)+' campaigns · '+nf(r.sent)+' sent · '+nf(r.replies)+' replies'+(r.ok?'':' (FAILED)'));
const allProbs=t.problems||[];
const skipped=allProbs.filter(p=>String(p).includes('no email'));
const probs=allProbs.filter(p=>!String(p).includes('no email'));
const skippedNames=skipped.map(p=>String(p).split(':')[0]);
const errCount=failed.length+probs.length;
const parts=['**'+results.length+' client(s), '+failed.length+' failed**','**Scope:** '+scope];
if(lines.length) parts.push('**Clients**\n'+lines.join('\n'));
parts.push('**Threads:** '+nf(t.checked)+' prospects checked · '+nf(t.updated)+' threads refreshed');
if(failed.length) parts.push('**FAILED ('+failed.length+')**\n'+failed.map(r=>'- '+r.client+': campaigns seen but none written').join('\n'));
if(skipped.length) parts.push('**Skipped ('+skipped.length+', no contact email)**\n'+skippedNames.join(', '));
if(t.scopeSkipped) parts.push('**Skipped ('+t.scopeSkipped+', prospect of a client outside this run\'s scope)**');
if(launch.clientFilter && !results.length) parts.push('**Skipped (1, client filter matched no PlusVibe client)**');
if(probs.length) parts.push('**Thread problems ('+probs.length+')**\n'+probs.map(p=>'- '+p).join('\n'));
const desc=parts.join('\n\n');
const row={
 'Automation':'Sync PlusVibe Campaigns to Hub',
 'Status': errCount>0 ? 'Succeeded with errors' : 'Succeeded',
 'Run at': $now.toISO(),
 'Records In': totalIn,
 'Records Out': totalOut,
 'Errors': errCount,
 'Target': 'Campaigns + Prospects',
 'Trigger': launch.trigger||'schedule',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': desc
};
// Client is attached only when the run served exactly one client; never an empty link array.
if(launch.clientFilter) row['Client']=[launch.clientFilter];
return [{ json: row }];

const pr=$('Loop Prospects').first().json||{};
const prf=pr.fields||pr;
const ct=$input.first().json||{};
const cf=ct.fields||ct;
const sd=$getWorkflowStaticData('global');
const clientIds=Array.isArray(prf.Client)?prf.Client:[];
const cm=(sd.clientMap||{})[clientIds[0]]||{};
const lead_email=String(cf.email||'').toLowerCase().trim();
const base={ prospectId:pr.id||'', prospectName:prf.Name||'', lead_email, pvWorkspace:cm.pvWorkspace||'' };
if(!lead_email||!cm.pvWorkspace){ return [{ json: Object.assign({pvUrl:''},base) }]; }
const u1='https://api.plusvibe.ai/api/v1/unibox/emails?workspace_id='+cm.pvWorkspace+'&lead='+lead_email+'&email_type=all';
const u2='https://api.plusvibe.ai/api/v1/unibox/campaign-emails?workspace_id='+cm.pvWorkspace+'&lead='+lead_email;
return [{ json: Object.assign({pvUrl:u1},base) }, { json: Object.assign({pvUrl:u2},base) }];

const items=$input.all();
const pl=$('Prep Lookup').first().json;
const leadEmail=(pl.lead_email||'').toLowerCase();
const sd=$getWorkflowStaticData('global');
sd.threadStats.checked++;
const prf=($('Loop Prospects').first().json.fields||{});
if(!leadEmail){ sd.threadStats.problems.push((pl.prospectName||pl.prospectId)+': contact fetch returned no email'); return [{ json: { prospectId: pl.prospectId, _skip:true } }]; }
if(!pl.pvWorkspace){ sd.threadStats.problems.push((pl.prospectName||pl.prospectId)+': client has no PV workspace'); return [{ json: { prospectId: pl.prospectId, _skip:true } }]; }
let rateLimited=false;
const pool=[];
for(const it of items){ const r=(it&&it.json)||{}; const arr=r.data||r.emails; if(Array.isArray(arr)){ pool.push(...arr); } else { const s=JSON.stringify(r).slice(0,600); if(s.includes('1015')||s.toLowerCase().includes('rate limit')) rateLimited=true; } }
if(rateLimited){ sd.threadStats.problems.push((pl.prospectName||pl.prospectId)+': PV rate limited, retries next run'); }
const emails=pool.filter(m=>String(m.lead||'').toLowerCase()===leadEmail);
const seen=new Set(); const uniq=[];
for(const m of emails){ const k=m.message_id||m.id||JSON.stringify([m.sent_on,m.subject]); if(!seen.has(k)){ seen.add(k); uniq.push(m); } }
if(!uniq.length) return [{ json: { prospectId: pl.prospectId, _skip:true } }];
const fmtTs=(ts)=>{const d=new Date(ts);if(isNaN(d.getTime()))return '';return d.toLocaleString('sv-SE',{timeZone:'Asia/Jerusalem'}).slice(0,16)+' IL';};
const rawBody=(m)=>{if(typeof m.text_body==='string'&&m.text_body.trim())return m.text_body;let h='';if(m.body&&typeof m.body==='object')h=(typeof m.body.text==='string'&&m.body.text.trim())?m.body.text:(m.body.html||'');else if(typeof m.body==='string')h=m.body;else h=m.snippet||'';h=h.replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<br\s*\/?>/gi,'\n').replace(/<\/(?:p|div|tr|li|h[1-6])>/gi,'\n\n').replace(/<[^>]*>/g,' ');return h;};
const clean=(t)=>{
if(!t)return '';
let s=String(t).replace(/\r\n?/g,'\n');
s=s.replace(/(?:\n|^)[ \t]*-{3,}\s*Original Message\s*-{3,}[\s\S]*$/i,'');
s=s.replace(/(?:\n|^)[ \t]*_{10,}[\s\S]*$/,'');
s=s.replace(/(?:\n|\s)On\s+\S[\s\S]{0,170}?wrote:[\s\S]*$/i,'');
s=s.replace(/\n\s*>[\s\S]*$/,'');
s=s.replace(/(?:\n|^)From:\s[\s\S]*$/i,'');
s=s.replace(/(?:\n|^)[ \t]*Sent from my [^\n]*[\s\S]*$/i,'');
s=s.replace(/[a-z]+\\?:\s*\{behavior:url\([^)]*\)[^}]*\}/gi,'');
s=s.replace(/[.#]?[a-z][\w-]*\s*\{[^}]*\}/gi,'');
s=s.replace(/&nbsp;/gi,' ').replace(/&[a-z#0-9]+;/gi,' ');
const SIGOFF=/^(?:thanks|thank you|thanks so much|many thanks|regards|best regards|kind regards|warm regards|best|cheers|sincerely|all the best|talk soon|speak soon)[,!.]*$/i;
const TITLE=/\b(?:ceo|cto|coo|cfo|cmo|cro|cpo|vp|svp|evp|president|founder|co-?founder|director|manager|head of|partner|principal|engineer|consultant|advisor|owner|officer|chief)\b/i;
const URLISH=/(?:https?:\/\/|www\.|\b[a-z0-9-]+\.(?:com|net|org|io|ai|co|dev|app)\b)/i;
const lines=s.split('\n');
const looksSig=(i)=>{let score=0;let shorts=0;for(let j=i+1;j<Math.min(lines.length,i+7);j++){const L=lines[j].trim();if(!L)continue;const dg=L.replace(/\D/g,'').length;if(dg>=9&&dg<=15&&/[\d)]/.test(L))score+=2;if(URLISH.test(L))score+=2;if(TITLE.test(L))score+=2;if(L.length<=40)shorts++;}if(shorts>=2)score+=2;return score>=2;};
let cut=-1;
for(let i=0;i<lines.length;i++){const L=lines[i].trim();if(/^--\s*$/.test(L)){cut=i;break;}if(SIGOFF.test(L)&&looksSig(i)){cut=i;break;}}
if(cut>0)s=lines.slice(0,cut).join('\n');
s=s.split('\n').map(x=>x.replace(/[^\S\n]+/g,' ').trim()).join('\n');
s=s.replace(/\n{3,}/g,'\n\n');
return s.trim();
};
const fromOf=(m)=>{if(typeof m.from==='string')return m.from;if(Array.isArray(m.from_address_json)&&m.from_address_json[0])return m.from_address_json[0].address||'';return m.from_address_email||m.from_email||'';};
const isIn=(m)=>{if(m.current_step!=null)return false;const d=String(m.direction||'').toUpperCase();if(d==='IN')return true;if(d==='OUT')return false;return fromOf(m).toLowerCase().includes(leadEmail);};
const tsOf=(m)=>m.sent_on||m.timestamp_created||m.created_at||'';
const sorted=uniq.sort((a,b)=>new Date(tsOf(a))-new Date(tsOf(b)));
const blocks=[]; const themTs=[]; const usTs=[];
for(const m of sorted){
  const body=clean(rawBody(m));
  if(body.length<2) continue;
  const dir=isIn(m)?'THEM':'US';
  const t=tsOf(m);
  if(dir==='THEM'&&t)themTs.push(t); if(dir==='US'&&t)usTs.push(t);
  blocks.push('**['+fmtTs(t)+'] '+dir+':**\n'+body);
}
let thread_context=blocks.join('\n\n');
if(thread_context.length>50000)thread_context=thread_context.slice(-50000);
if(!thread_context) return [{ json: { prospectId: pl.prospectId, _skip:true } }];
const iso=(t)=>{const d=new Date(t);return isNaN(d.getTime())?'':d.toISOString();};
const firstThem=themTs.length?iso(themTs[0]):(prf['First Engagement']||'');
const lastThem=themTs.length?iso(themTs[themTs.length-1]):(prf['Last Engaged']||'');
const lastUs=usTs.length?iso(usTs[usTs.length-1]):(prf['Last Touch']||'');
const current=''+(prf['Conversation Thread']||'');
if(thread_context.trim()===current.trim() && (!lastThem||prf['Last Engaged']) && (!lastUs||prf['Last Touch'])) return [{ json: { prospectId: pl.prospectId, _skip:true } }];
sd.threadStats.updated++;
return [{ json: { prospectId: pl.prospectId, 'Conversation Thread': thread_context, 'First Engagement': firstThem, 'Last Engaged': lastThem, 'Last Touch': lastUs } }];

const r=$input.first().json||{};
const f=r.fields||r;
const clientRecId=r.id||'';
const clientName=f['Client']||'';
const pvWorkspace=String(f['PlusVibe Workspace ID']||'').trim();
const clientSlug=String(clientName).toLowerCase().replace(/[^a-z0-9]/g,'');
return [{ json: { clientRecId, clientName, pvWorkspace, clientSlug } }];

const clientRecId=$('Parse Client').first().json.clientRecId||'';
const raw=[];
for(const it of $input.all()){
  const j=it.json||{};
  const arr=Array.isArray(j)?j:(Array.isArray(j.campaigns)?j.campaigns:(Array.isArray(j.data)?j.data:[j]));
  for(const c of arr){ if(c&&(c.id||c._id)) raw.push(c); }
}
if(!raw.length) return [{ json: { _keepAlive:true } }];
return raw.map(c=>({ json: {
  'Campaign': c.camp_name||c.id||c._id||'',
  'Campaign ID': c.id||c._id||'',
  'Client': clientRecId?[clientRecId]:[],
  'Sequencer':'PlusVibe',
  'Channel':'Email',
  'Status': c.status||'',
  'Leads': c.lead_count||0,
  'Contacted': c.lead_contacted_count||0,
  'Completed': c.completed_lead_count||0,
  'Messages Sent': c.sent_count||0,
  'Replies': c.replied_count||0,
  'Positive Replies (PV)': c.positive_reply_count||0,
  'Bounced': c.bounced_count||0,
  'Opens': c.opened_count||0,
  'Unique Opens': c.unique_opened_count||0,
  'Open Tracking': !!c.is_emailopened_tracking,
  'Last Sent': c.last_lead_sent||'',
  'Created': c.created_at||'',
  'Last Synced': $now.toISO()
}}));

const sd=$getWorkflowStaticData('global');
if(!Array.isArray(sd.pvSyncResults)) sd.pvSyncResults=[];
let clientRecId='', clientName='';
try{ const p=$('Parse Client').first().json; clientRecId=p.clientRecId||''; clientName=p.clientName||''; }catch(e){}
let rows=[]; try{ rows=$('Format Campaign Rows').all().map(i=>i.json).filter(r=>r&&r['Campaign ID']); }catch(e){}
let upserted=[]; try{ upserted=$('Upsert Campaigns').all().map(i=>i.json); }catch(e){}
const seen=rows.length;
const written=upserted.length;
const sent=rows.reduce((s,r)=>s+(r['Messages Sent']||0),0);
const replies=rows.reduce((s,r)=>s+(r['Replies']||0),0);
const positives=rows.reduce((s,r)=>s+(r['Positive Replies (PV)']||0),0);
const ok=!(seen>0 && written===0);
sd.pvSyncResults.push({client:clientName||'(unknown)', clientRecId, campaigns:seen, written, sent, replies, positives, ok});
return [{ json: { client:clientName||'', ok } }];

// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd=$getWorkflowStaticData('global');
let launch=null;
try{ const r=$('Fetch Launch Record').first().json; if(r&&r.id) launch=r; }catch(e){}
const f=(launch&&launch.fields)||launch||{};
const cl=Array.isArray(f.Client)&&f.Client.length?f.Client[0]:'';
const clientFilter=(cl&&typeof cl==='object')?String(cl.id||''):String(cl||'');
sd.launch={ recordId: launch?String(launch.id):'', trigger: launch?'form':'schedule', clientFilter, startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];
